export class DominionWarUniformPack
  extends BaseTngEraUniformPack
  implements IUniformPack
{
  constructor() {
    super(UniformEra.DominionWar);
  }

  getUniformSwatches(species: Species) {
    if (species === Species.Edosian) {
      return [
        new Swatch(
          BodyType.AverageNonBinary,
          'Average Edosian',
          (token) =>
            UniformCatalog.decorateSwatch(
              this.getNeck(
                BodyType.AverageNonBinary,
                token.skinColor,
                Species.Edosian,
                UniformEra.DominionWar,
              ) + DominionWarUniforms.edosian.standard,
              BodyType.AverageNonBinary,
              token,
            ),
          'Species.edosian',
        ),
      ];
    } else {
      return [
        new Swatch(
          BodyType.AverageMale,
          'Average Male',
          (token) =>
            UniformCatalog.decorateSwatch(
              this.getUniformAndVariantByBodyType(
                token,
                UniformVariantType.Base,
                BodyType.AverageMale,
              ),
              BodyType.AverageMale,
              token,
            ),
          'BodyType.averageMale',
        ),
        new Swatch(
          BodyType.AverageFemale,
          'Average Female',
          (token) =>
            UniformCatalog.decorateSwatch(
              this.getUniformAndVariantByBodyType(
                token,
                UniformVariantType.Base,
                BodyType.AverageFemale,
              ),
              BodyType.AverageFemale,
              token,
            ),
          'BodyType.averageFemale',
        ),
        new Swatch(
          BodyType.AverageNonBinary,
          'Average Non-Binary',
          (token) =>
            UniformCatalog.decorateSwatch(
              this.getUniformAndVariantByBodyType(
                token,
                UniformVariantType.Base,
                BodyType.AverageNonBinary,
              ),
              BodyType.AverageNonBinary,
              token,
            ),
          'BodyType.averageNonBinary',
        ),
      ];
    }
  }

  getUniformVariantSwatches(token: TokenModel) {
    return [];
  }

  getUniformAndVariantBody(token: TokenModel) {
    return this.getUniformAndVariantByBodyType(
      token,
      token.variant,
      token.bodyType,
    );
  }

  getUniformAndVariantByBodyType(
    token: TokenModel,
    variant: UniformVariantType,
    bodyType: BodyType,
  ) {
    let result = '';

    if (token.species === Species.Cetacean) {
      result =
        this.getNeck(
          bodyType,
          token.skinColor,
          token.species,
          UniformEra.DominionWar,
        ) + DominionWarCetaceanBody;
    } else if (token.species === Species.Edosian) {
      result =
        this.getNeck(
          bodyType,
          token.skinColor,
          token.species,
          UniformEra.DominionWar,
        ) + DominionWarUniforms.edosian.standard;
    } else if (bodyType === BodyType.AverageMale) {
      if (this.isAdmiralty(token)) {
        result =
          this.getNeck(
            bodyType,
            token.skinColor,
            token.species,
            UniformEra.DominionWar,
          ) + DominionWarUniforms.male.admiralty;
      } else {
        result =
          this.getNeck(
            bodyType,
            token.skinColor,
            token.species,
            UniformEra.DominionWar,
          ) + DominionWarMaleBody;
      }
    } else if (bodyType === BodyType.AverageNonBinary) {
      if (this.isAdmiralty(token)) {
        result =
          this.getNeck(
            BodyType.AverageFemale,
            token.skinColor,
            token.species,
            UniformEra.DominionWar,
          ) + DominionWarUniforms.nonBinary.admiralty;
      } else {
        result =
          this.getNeck(
            BodyType.AverageFemale,
            token.skinColor,
            token.species,
            UniformEra.DominionWar,
          ) + DominionWarUniforms.nonBinary.standard;
      }
    } else {
      if (this.isAdmiralty(token)) {
        result =
          this.getNeck(
            bodyType,
            token.skinColor,
            token.species,
            UniformEra.DominionWar,
          ) + DominionWarUniforms.female.admiralty;
      } else {
        result =
          this.getNeck(
            bodyType,
            token.skinColor,
            token.species,
            UniformEra.DominionWar,
          ) + DominionWarFemaleBody;
      }
    }

    if (isCadetRank(token.rankIndicator)) {
      return result
        .replace(/#7d7d7d/g, token.divisionColor)
        .replace(/#2d2d2d/g, '#7d7d7d')
        .replace(DefaultRed, '#7d7d7d')
        .replace(SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX, token.skinColor);
    } else {
      return result
        .replace(DefaultRed, token.divisionColor)
        .replace(SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX, token.skinColor);
    }
  }

  getRankIndicator(token: TokenModel) {
    let result = super.getRankIndicator(token);
    if (token.species === Species.Cetacean) {
      result =
        `<g transform="rotate(-21.492033,417.22301,211.31432)">` +
        result +
        `</g>`;
    } else if (token.species === Species.Edosian) {
      result = `<g transform="translate(-2, 2)">` + result + `</g>`;
    } else if (!isCadetRank(token.rankIndicator)) {
      result = `<g transform="translate(3, 5)">` + result + `</g>`;
    }
    return result;
  }
}
